algorithm CountFailing
    define mutable count as integer <- 0;
    define mutable grade as integer <- 0;
    read count;
    define mutable failing as integer <- 0;
    for i <- 1 to count step 1 do
        read grade;
        if grade < 5 then
            failing <- failing + 1;
        endIf
    endFor
    write failing;
endAlgorithm

