algorithm CountPassing
    define mutable count as integer <- 0;
    define mutable grade as integer <- 0;
    define mutable passing as integer <- 0;
    read count;
    passing <- 0;
    for i <- 1 to count step 1 do
        read grade;
        if grade >= 5 then
            passing <- passing + 1;
        endIf
    endFor
    write passing;
endAlgorithm
